}
struct AudioSlot {
    generation: u64,
    audio: Option<Vec<u8>>,
}
struct AudioQueue {
    next: u64,
    emit: u64,
    slots: BTreeMap<u64, AudioSlot>,
}
impl AudioQueue {
    fn new() -> Self {
        Self {
            next: 0,
            emit: 0,
            slots: BTreeMap::new(),
        }
    }
    fn reserve(&mut self, generation: u64) -> u64 {
        let sequence = self.next;
        self.next += 1;
        self.slots.insert(
            sequence,
            AudioSlot {
                generation,
                audio: None,
            },
        );
        sequence
    }
    fn finish(&mut self, sequence: u64, generation: u64, audio: Vec<u8>) -> Vec<Event> {
        let Some(slot) = self.slots.get_mut(&sequence) else {
            return Vec::new();
        };
        if slot.generation == generation {
            slot.audio = Some(audio);
        } else {
            slot.audio = Some(Vec::new());
        }
        let mut ready = Vec::new();
        while let Some(slot) = self.slots.get(&self.emit) {
            if slot.audio.is_none() {
                break;
            }
            let slot = self.slots.remove(&self.emit).expect("audio slot exists");
            if let Some(audio) = slot.audio {
                if !audio.is_empty() {
                    ready.push(Event::Audio {
                        audio,
                        generation: slot.generation,
                        sequence: self.emit,
                    });
                }
            }
            self.emit += 1;
        }
        ready
    }
    fn clear(&mut self) {
        self.slots.clear();
        self.emit = self.next;
    }
}

#[derive(Debug)]
pub struct Clip {
    id: String,
    audio: Vec<u8>,
    _mime: String,
    // Stamped when the clip is accepted, not when its transcript comes back.
    // Transcription is a sidecar round trip, and a page transfer can land
    // inside it; without this the reply epoch would be read after the rescue
